package lk.ac.sliit.ridelink.driver.infrastructure.persistence.adapter;
import lk.ac.sliit.ridelink.driver.domain.enums.VehicleType; import lk.ac.sliit.ridelink.driver.domain.model.DriverProfile; import lk.ac.sliit.ridelink.driver.domain.repository.DriverProfileRepository; import lk.ac.sliit.ridelink.driver.infrastructure.persistence.mapper.DriverPersistenceMapper; import lk.ac.sliit.ridelink.driver.infrastructure.persistence.repository.SpringDataDriverRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class DriverPersistenceAdapter implements DriverProfileRepository { private final SpringDataDriverRepository r; public DriverPersistenceAdapter(SpringDataDriverRepository r){this.r=r;} public DriverProfile save(DriverProfile d){return DriverPersistenceMapper.domain(r.save(DriverPersistenceMapper.entity(d)));} public Optional<DriverProfile> findById(UUID id){return r.findById(id).map(DriverPersistenceMapper::domain);} public Optional<DriverProfile> findByAccountId(UUID id){return r.findByAccountId(id).map(DriverPersistenceMapper::domain);} public boolean existsByAccountId(UUID id){return r.existsByAccountId(id);} public boolean existsByLicenceNumber(String v){return r.existsByLicenceNumberIgnoreCase(v);} public List<DriverProfile> findEligible(String area,VehicleType type){return r.findEligible(area,type).stream().map(DriverPersistenceMapper::domain).toList();} }
